section.sourcecode:
exact-claim = {
  1: "taa.exact-computation-claim.v1",
  2: artifact,
  3: claim,
  4: verifier,
  5: evidence,
  6: tstr,                  ; issue time, UTC
  ? 7: tstr                 ; replaces statement
}
artifact = {
  1: "sha-256", 2: bstr .size 32,
  3: tstr, ? 4: tstr
}
claim = {
  1: tstr, 2: tstr,
  3: "certified" / "broken" / "unknown",
  4: tstr, 5: [* tstr]
}
verifier = {
  1: tstr, 2: tstr,
  3: "sha-256", 4: bstr .size 32
}
evidence = {
  1: "sha-256", 2: bstr .size 32,
  ? 3: tstr, ? 4: tstr
}
